    if(!cap('manage')){document.querySelectorAll('.dialog input:not([type=search]),.dialog select,.dialog textarea').forEach(el=>el.disabled=true);document.querySelectorAll('.dialog [data-action]').forEach(el=>{if(/^(handout-(edit|attach|detach|delete)-|brief-voice-)/.test(el.dataset.action)||['knowledge-all','tool-upload-approve','tool-upload-save','template-save'].includes(el.dataset.action))el.disabled=true;});}
    const current=toolStack.at(-1);for(const item of current.form||[]){const el=document.getElementById(item.key)||document.querySelector('.dialog [name="'+CSS.escape(item.key)+'"]');if(!el)continue;if(item.type==='file'){if(item.files?.length){const dt=new DataTransfer();item.files.forEach(f=>dt.items.add(f));el.files=dt.files;}}else if(item.type==='checkbox')el.checked=item.checked;else el.value=item.value;}toolFormDirty=Boolean(current.dirty);
